sys_script_include.script:
var test2 = Class.create();
test2.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	isBlank: function(v) {
		if(v === null || v === undefined) return true;
	},
	getDisplayBySysId: function(tableName, sysId) {
		if (this.isBlank(tableName) || this.isBlank(sysId)) return '';

		var gr = new GlideRecord(tableName);
		if(!gr.isValid()) return '';
		if(!gr.get(sysId)) return '';

		return gr.getDisplayValue();
	},
    type: 'test2'
});
